using System.Text;

class Program
{
    static void Main()
    {
        int k = int.Parse(Console.ReadLine().Trim());
        string pesan = Console.ReadLine() ?? "";
        var sb = new StringBuilder();
        foreach (char c in pesan) sb.Append(c >= 'a' && c <= 'z' ? (char)('a' + (c - 'a' + k) % 26) : c);
        Console.WriteLine(sb.ToString());
    }
}

