using System;

class Program
{
    static void Main()
    {
        var t = Console.In.ReadToEnd().Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        string a = t[0], b = t[1];
        if (string.Equals(a, b, StringComparison.OrdinalIgnoreCase)) Console.WriteLine("sama");
        else Console.WriteLine("beda");
    }
}
